159	  async validateAndSetApiToken(
160	    token: string,
161	    apiHost: string,
162	  ): Promise<{
163	    user: CloudUser;
164	    organization: CloudOrganization;
165	    app: CloudApp;
166	    hasActiveLicense: boolean;
167	  }> {
168	    try {
169	      const { fetchWithProxy } = await import('../util/fetch');
170	      const response = await fetchWithProxy(`${apiHost}/api/v1/users/me`, {
171	        headers: {
172	          Authorization: `Bearer ${token}`,
173	        },
174	      });
175	
176	      if (!response.ok) {
177	        const errorMessage = await response.text();
178	        logger.error(
179	          `[Cloud] Failed to validate API token: ${errorMessage}. HTTP Status: ${response.status} - ${response.statusText}.`,
180	        );
181	        throw new Error('Failed to validate API token: ' + response.statusText);
182	      }
183	
184	      const { user, organization, app, hasActiveLicense } = await response.json();
185	      this.setApiKey(token);
186	      this.setApiHost(apiHost);
187	      this.setAppUrl(app.url);
188	      if (typeof hasActiveLicense === 'boolean') {
189	        const createdAt = user?.createdAt ? new Date(user.createdAt) : null;
190	        const isGrandfathered = createdAt != null && createdAt < SHARING_CUTOFF_DATE;
191	        this.setSharing(hasActiveLicense || isGrandfathered);
192	      }
193	
194	      return {
195	        user,
196	        organization,
197	        app,
198	        hasActiveLicense: typeof hasActiveLicense === 'boolean' ? hasActiveLicense : false,
199	      };
200	    } catch (err) {
201	      const error = err as Error & { cause?: string };
202	      const errorMessage = error instanceof Error ? error.message : String(error);
203	      logger.error(`[Cloud] Failed to validate API token with host ${apiHost}: ${errorMessage}`);
204	      if (error.cause) {
205	        logger.error(`Cause: ${error.cause}`);
206	      }
207	      throw error;
208	    }
209	  }
