109	function extractEvalConfigPayload(body: unknown): Record<string, unknown> {
110	  if (!isRecord(body)) {
111	    throw new Error('Invalid cloud eval config response: expected a JSON object.');
112	  }
113	
114	  const bodyConfig = isRecord(body.config) ? body.config : undefined;
115	  if (!bodyConfig) {
116	    if (looksLikeEvalConfig(body)) {
117	      return body;
118	    }
119	    throw new Error('Invalid cloud eval config response: missing "config" object.');
120	  }
121	
122	  const nestedConfig = isRecord(bodyConfig.config) ? bodyConfig.config : undefined;
123	  if (!nestedConfig) {
124	    return {
125	      ...bodyConfig,
126	      ...(typeof bodyConfig.name !== 'string' && typeof body.name === 'string'
127	        ? { name: body.name }
128	        : {}),
129	    };
130	  }
131	
132	  return {
133	    ...nestedConfig,
134	    ...(typeof nestedConfig.name !== 'string' && typeof bodyConfig.name === 'string'
135	      ? { name: bodyConfig.name }
136	      : {}),
137	  };
138	}
