   * @param apiHost - The API host to validate against.
   * @returns The user, organization, app, and optional license status from the API response.
   * @throws Error if the token could not be validated.
   */
  async validateApiToken(
    token: string,
    apiHost: string,
  ): Promise<{
    user: CloudUser;
    organization: CloudOrganization;
    app: CloudApp;
    hasActiveLicense?: boolean;
  }> {
