import type { Command } from 'commander';

interface AccessibleTeam {
  id: string;
  name: string;
  slug: string;
  organizationId: string;
  createdAt: string;
  updatedAt: string;
}

/**
 * Finds a team within a list by identifier, matching on id first, then case-insensitive
 * display name, then slug (in that priority order).
 */
function findTeamByIdentifier(
  teams: AccessibleTeam[],
  identifier: string,
): AccessibleTeam | undefined {
  return (
    teams.find((t) => t.id === identifier) ||
    teams.find((t) => t.name.toLowerCase() === identifier.toLowerCase()) ||
    teams.find((t) => t.slug === identifier)
  );
}

/**
 * Returns the team with the earliest createdAt date (the oldest team).
 */
function getOldestTeam(teams: AccessibleTeam[]): AccessibleTeam {
  return [...teams].sort(
